<form class="panel form-grid" method="post" action="<?=url('actions/donation-actions.php')?>"><?=csrf()?><input type="hidden" name="action" value="<?=isset($d['id'])?'edit':'create'?>"><input type="hidden" name="id" value="<?=e($d['id']??'')?>"><?php input('Donation title','title','text',$d['title']??'','maxlength="120"');input('Servings (estimated people fed)','quantity','number',$d['quantity']??'','min="1" max="10000"');foreach(['food_type'=>['Vegetarian','Non-vegetarian','Vegan'],'category'=>['Cooked meals','Produce','Bakery','Packaged food']] as $name=>$opts):?><label><?=ucfirst(str_replace('_',' ',$name))?><select name="<?=$name?>"><?php foreach($opts as $opt):?><option <?=($d[$name]??'')===$opt?'selected':''?>><?=$opt?></option><?php endforeach;?></select></label><?php endforeach;input('City','city','text',$d['city']??$u['city'],'maxlength="100"');input('Collect before (India time)','deadline','datetime-local',isset($d['deadline'])?date('Y-m-d\TH:i',strtotime($d['deadline'])):'','min="'.date('Y-m-d\TH:i').'"');?><label class="span2">Pickup address<textarea name="address" maxlength="500" required><?=e($d['address']??$u['address'])?></textarea></label><label class="span2">Food description, preparation time and storage details<textarea name="description" maxlength="3000" required><?=e($d['description']??'')?></textarea></label><label class="span2">Allergens (write “Unknown” if unsure)<input name="allergens" value="<?=e($d['allergens']??'')?>" maxlength="255" required></label><p class="span2 muted">Only share food you believe is safe to eat. Keep it stored appropriately and agree a timely pickup.</p><button class="button span2">Save donation <?=icon('arrow')?></button></form>